INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_tc_pb_basic_tag_aggr_1d
partition (grass_region = ${grass_region},local_date = ${local_date}, local_hour)
select  is_item_card
        ,user_id
        ,is_ads
        ,mapping_general
        ,a.shop_id
        ,a.item_id
        ,a.model_id

        ,if(b.item_id is not null,1,0) as cheapest_item
        ,if(c.item_id is not null,1,0) as cheapest_cspu_all_item
        ,if(b1.model_id is not null,1,0) as cheapest_model
        ,if(c1.model_id is not null,1,0) as cheapest_cspu_all_model

        ,coalesce(b1.shop_scs_type,b.shop_scs_type,c1.shop_scs_type,c.shop_scs_type,'') as shop_scs_type
        ,null as cspu_pr_rate

        ,imp_cnt
        ,click_cnt
        ,order_cnt
        ,gmv
        ,gmv_local
        ,pc2_gmv

        ,a.local_hour
from    (
    select  *
    from    srdi_mart.dws_sr_data_warehouse_tc_pb_basic_aggr_1d
    where   grass_region = ${grass_region}
      and   local_date = ${local_date}
      and   mapping_general in ('Post Purchase', 'Daily Discover', 'Search', 'You May Also Like', 'Shop', 'S&R__ALL__', '__ALL__' , 'Video', 'Live Streaming')
) as a
left join  cheapest_item_list_${grass_region_without_quote} b on  a.item_id=b.item_id and a.local_hour=b.cheapest_hour
left join  cheapest_cspu_all_item_${grass_region_without_quote} c on a.item_id=c.item_id and a.local_hour=c.local_hour
left join  cheapest_model_list_${grass_region_without_quote} b1 on  a.item_id=b1.item_id and a.model_id=b1.model_id and a.local_hour=b1.cheapest_hour
left join  cheapest_cspu_all_model_${grass_region_without_quote} c1 on a.item_id=c1.item_id and a.model_id=c1.model_id and a.local_hour=c1.local_hour
;
